class WordDictionary {
    private WordDictionary[] children;
    private boolean isEnd;

    public WordDictionary() {
        children = new WordDictionary[26];
        isEnd = false;
    }

    public void addWord(String word) {
        WordDictionary node = this;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                node.children[idx] = new WordDictionary();
            }
            node = node.children[idx];
        }
        node.isEnd = true;
    }

    public boolean search(String word) {
        return dfs(word, 0, this);
    }

    private boolean dfs(String word, int pos, WordDictionary node) {
        if (pos == word.length()) return node.isEnd;
        char c = word.charAt(pos);
        if (c == '.') {
            for (int i = 0; i < 26; i++) {
                if (node.children[i] != null && dfs(word, pos + 1, node.children[i])) {
                    return true;
                }
            }
            return false;
        } else {
            int idx = c - 'a';
            if (node.children[idx] == null) return false;
            return dfs(word, pos + 1, node.children[idx]);
        }
    }
}

import java.util.*;

class WordDictionary {
    private Map<Integer, List<String>> wordsByLength;

    public WordDictionary() {
        wordsByLength = new HashMap();
    }

    public void addWord(String word) {
        int len = word.length();
        if (!wordsByLength.containsKey(len)) {
            wordsByLength.put(len, new ArrayList());
        }
        wordsByLength.get(len).add(word);
    }

    public boolean search(String word) {
        int len = word.length();
        if (!wordsByLength.containsKey(len)) return false;
        List<String> candidates = wordsByLength.get(len);
        for (int i = 0; i < candidates.size(); i++) {
            if (matches(word, candidates.get(i))) return true;
        }
        return false;
    }

    private boolean matches(String pattern, String word) {
        for (int i = 0; i < pattern.length(); i++) {
            char p = pattern.charAt(i);
            if (p != '.' && p != word.charAt(i)) return false;
        }
        return true;
    }
}
